-- ============================================================
--  124_experiencias_farmacoterapia_diabetes.sql — Experiencias de clase: Curso de Farmacoterapia de la Diabetes
--
--  Generado por scripts/generar-migracion-experiencias.mjs farmacoterapia-diabetes
--  a partir de contenido/experiencias/farmacoterapia-diabetes. No editar a mano.
--
--  10 clases con experiencia interactiva (mapa conceptual,
--  mapa de proceso, caso, errores frecuentes, repaso, resumen y
--  referencias): 59.241 caracteres de lectura, mínimo
--  5.316 por clase.
--
--  Por clase: si no está, avisa y sigue; si no tiene experiencia,
--  retira (borrado lógico) el texto corto de la siembra e inserta la
--  experiencia como primer bloque, conservando videos y enlaces; si ya
--  la tiene, la actualiza. Si el curso está publicado, deja aprobada
--  una versión nueva (077). Nunca detiene el arranque.
-- ============================================================

DO $exp$
DECLARE
  v_curso BIGINT;
  v_clase BIGINT;
  v_data  JSONB;
  v_n     INTEGER := 0;
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = $t$Curso de Farmacoterapia de la Diabetes$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'Experiencias: no existe el curso %. Se salta.', $t$Curso de Farmacoterapia de la Diabetes$t$;
    RETURN;
  END IF;

  -- 01. Introducción al curso: la farmacoterapia de la diabetes en Colombia y el papel del QF
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La señora Rosa y la pregunta que nadie le hizo","texto":"Rosa tiene 58 años, vive en Sincelejo y hace tres meses le diagnosticaron diabetes tipo 2. En la farmacia pregunta si puede seguir tomando el “remedio para la presión” que le dio el vecino y si la metformina “daña el riñón”. Tiene tres medicamentos, dos controles pendientes y ninguna explicación clara. El Químico Farmacéutico que la atiende puede resolver esas dudas, detectar un problema de seguridad y ayudarla a llegar mejor a su próxima consulta. Esa es la farmacoterapia de la diabetes en la vida real."},"objetivos":["Describir el papel del Químico Farmacéutico en la farmacoterapia de la diabetes en Colombia.","Reconocer los problemas de seguridad y adherencia más frecuentes en la consulta farmacéutica.","Relacionar las metas glucémicas con la selección del tratamiento y el seguimiento.","Ubicar las cinco unidades del curso y los casos que se resolverán."],"conceptos":[{"icono":"Activity","termino":"Diabetes tipo 2","definicion":"Enfermedad crónica en la que la resistencia a la insulina y la disfunción de la célula beta elevan la glucosa. El tratamiento combina cambios de estilo de vida, medicamentos y seguimiento."},{"icono":"Pill","termino":"Farmacoterapia","definicion":"Selección, dosificación, educación y seguimiento de los medicamentos para alcanzar metas clínicas sin causar daño."},{"icono":"Users","termino":"Atención farmacéutica","definicion":"Proceso centrado en la persona que identifica, previene y resuelve problemas relacionados con los medicamentos."},{"icono":"Target","termino":"Meta individualizada","definicion":"Objetivo de HbA1c y de tiempo en rango adaptado a la edad, las comorbilidades, el riesgo de hipoglucemia y las preferencias."}],"secciones":[{"titulo":"La diabetes no se trata solo con una pastilla","parrafos":["La diabetes tipo 2 es una enfermedad progresiva. Al diagnóstico, la célula beta suele haber perdido parte de su función y la resistencia a la insulina ya lleva años. Por eso el tratamiento no es estático: cambia con la enfermedad, con el peso, con la función renal, con la aparición de enfermedad cardiovascular o insuficiencia cardíaca y con la edad. La farmacoterapia debe reevaluarse en cada control, no repetirse como una receta heredada.","En Colombia, la diabetes es una de las principales causas de enfermedad renal crónica, amputación y eventos cardiovasculares. El Químico Farmacéutico ve a la persona antes y después de la consulta, en la droguería, en el hospital o en el programa de crónicos. Esa posición permite detectar hipoglucemias, errores de dosis, interacciones y barreras de acceso que no siempre aparecen en la historia clínica."]},{"titulo":"Qué puede hacer el Químico Farmacéutico","parrafos":["El QF puede revisar la indicación, la efectividad, la seguridad y la adherencia de cada medicamento. Puede verificar si la metformina está contraindicada por función renal, si el paciente usa insulina y no sabe corregir una hipoglucemia, si el agonista GLP-1 está guardado en el lugar equivocado o si un producto “natural” promete curar la diabetes. También puede educar sobre alimentación, actividad física, automonitoreo y vacunación.","La intervención no reemplaza al médico. Se documenta y se comunica con el equipo tratante. Un mensaje claro, con datos y una propuesta concreta, mejora la aceptación. Por ejemplo: “La paciente tiene TFG de 28 ml/min; propongo suspender metformina y revisar el esquema con un iSGLT2 ajustado”."]},{"titulo":"Cómo está organizado el curso","parrafos":["La unidad 1 cubre fisiopatología, diagnóstico, metas y el algoritmo ADA 2026. La unidad 2 revisa metformina, iDPP-4, sulfonilureas y pioglitazona. La unidad 3 entra a los iSGLT2, los agonistas GLP-1 y tirzepatida. La unidad 4 trabaja insulinas, dispositivos, monitoreo continuo e hipoglucemia. La unidad 5 integra comorbilidad cardiorrenal, obesidad, seguimiento farmacoterapéutico y farmacovigilancia.","Cada clase trae un caso, un mapa conceptual y un proceso para practicar. Al final, un anexo con fichas de metformina, semaglutida, tirzepatida, dapagliflozina y liraglutida. La idea no es memorizar dosis aisladas, sino aprender a decidir con el paciente y con la evidencia."]}],"errores":[{"error":"Creer que la metformina “daña el riñón”.","correccion":"La metformina no es nefrotóxica, pero se acumula si la función renal cae y aumenta el riesgo de acidosis láctica. Hay que ajustar o suspender según la TFG."},{"error":"Hablar solo de la glucosa y olvidar el riesgo cardiovascular y renal.","correccion":"La selección del tratamiento depende también de la enfermedad cardiovascular, la insuficiencia cardíaca, la enfermedad renal y el peso."},{"error":"Entregar el medicamento sin preguntar cómo lo toma.","correccion":"La técnica, el horario, la conservación y la comprensión son parte de la dispensación."}],"comprueba":[{"pregunta":"¿Cuál es el papel central del QF en diabetes?","respuesta":"Evaluar, optimizar, educar y vigilar la farmacoterapia, en coordinación con el equipo tratante."},{"pregunta":"¿Por qué la diabetes exige reevaluar el tratamiento?","respuesta":"Porque la función de la célula beta, la función renal, el peso y las comorbilidades cambian con el tiempo."},{"pregunta":"¿Qué datos mínimos debe revisar antes de una intervención?","respuesta":"HbA1c, glucometrías, función renal, peso, presión, medicamentos, eventos de hipoglucemia y adherencia."}],"resumen":["La diabetes tipo 2 es **progresiva** y el tratamiento cambia con la persona.","El QF detecta problemas de **seguridad, adherencia y acceso** que impactan el control.","La intervención se documenta y se comunica con el equipo tratante.","El curso integra fisiopatología, fármacos, insulina, comorbilidad y seguimiento."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"},{"cita":"INVIMA. Código Único de Medicamentos vigentes (datos.gov.co).","url":"https://www.datos.gov.co/d/i7cb-raxc"}],"imagenes":[{"ubicacion":"Apertura de la clase","descripcion":"Ilustración de una farmacia comunitaria con una paciente mayor y un Químico Farmacéutico revisando una caja de metformina y una libreta de glucometrías.","alt":"Químico Farmacéutico revisando el tratamiento de una paciente con diabetes"}],"keywords":["curso de farmacoterapia de la diabetes","diabetes tipo 2 farmacoterapia","rol del químico farmacéutico en diabetes","metformina y riñón","atención farmacéutica diabetes colombia","seguimiento farmacoterapéutico diabetes","educación al paciente con diabetes","ada 2026 diabetes"],"mapa":{"centro":"El QF en la diabetes","ramas":[{"titulo":"Evaluar","icono":"Search","nodos":["Historia clínica y medicamentos","HbA1c, glucosa y función renal","Riesgo de hipoglucemia"]},{"titulo":"Optimizar","icono":"Target","nodos":["Meta individualizada","Comorbilidad cardiorrenal","Costo y adherencia"]},{"titulo":"Educar","icono":"GraduationCap","nodos":["Técnica de inyección","Hipoglucemia","Días de enfermedad"]},{"titulo":"Vigilar","icono":"LineChart","nodos":["Efectos adversos","Interacciones","Farmacovigilancia"]}]},"proceso":{"titulo":"Cómo se aborda una persona con diabetes en la farmacia","intro":"Un orden sencillo evita olvidar lo importante.","pasos":[{"titulo":"Recibir y escuchar","detalle":"Preguntar qué le preocupa, qué medicamentos usa y cómo los toma. Incluir productos naturales y medicamentos de venta libre.","icono":"Users","evidencia":"Entrevista documentada."},{"titulo":"Revisar datos","detalle":"HbA1c, glucometrías, función renal, peso, presión y eventos de hipoglucemia.","icono":"FileSearch","evidencia":"Datos en la ficha farmacéutica."},{"titulo":"Detectar problemas","detalle":"Identificar dosis inadecuadas, interacciones, barreras de acceso o falta de educación.","icono":"AlertTriangle","evidencia":"Problema relacionado con el medicamento."},{"titulo":"Intervenir y educar","detalle":"Proponer un cambio al equipo y enseñar lo que el paciente necesita saber.","icono":"Lightbulb","evidencia":"Nota de intervención."},{"titulo":"Seguir","detalle":"Acordar una fecha de control y revisar el efecto de la intervención.","icono":"CalendarClock","evidencia":"Seguimiento registrado."}]},"caso":{"titulo":"La metformina y el riñón","contexto":"Rosa tiene TFG estimada de 36 ml/min/1,73 m² y toma metformina 1 g cada 12 horas. No tiene acidosis, pero refiere diarrea intermitente y no ha vuelto al control.","pregunta":"¿Cuál es la intervención más razonable del Químico Farmacéutico?","opciones":[{"texto":"Suspender la metformina de inmediato y no comentar nada al médico.","correcta":false,"retro":"La suspensión puede ser necesaria, pero debe evaluarse y comunicarse. No se cambia un tratamiento crónico sin coordinación."},{"texto":"Revisar la dosis y la función renal, explicar los síntomas digestivos y proponer al médico ajustar el esquema y controlar la TFG.","correcta":true,"retro":"Con TFG entre 30 y 45 ml/min la metformina no se inicia y, si ya está en uso, se revisa la dosis y el riesgo. La intervención incluye educación y seguimiento."},{"texto":"Cambiar a glibenclamida porque no afecta el riñón.","correcta":false,"retro":"La glibenclamida puede causar hipoglucemia, sobre todo en enfermedad renal. No es un cambio automático ni seguro."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción al curso: la farmacoterapia de la diabetes en Colombia y el papel del QF$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción al curso: la farmacoterapia de la diabetes en Colombia y el papel del QF$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 02. Fisiopatología y clasificación de la diabetes: tipo 1, tipo 2 y otros tipos
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Dos pacientes, dos diabetes distintas","texto":"Andrés tiene 19 años, bajó 8 kg en dos meses y llegó con glucosa de 420 mg/dL y cetonas en orina. Doña Marta tiene 62 años, obesidad central, hipertensión y glucosa de 180 mg/dL sin cetonas. Los dos tienen diabetes, pero el mecanismo, el tratamiento inicial y el riesgo de complicaciones son distintos. Confundir el tipo puede llevar a una terapia insuficiente o a una hipoglucemia grave."},"objetivos":["Diferenciar diabetes tipo 1, tipo 2, gestacional y otros tipos específicos.","Explicar el papel de la resistencia a la insulina, la célula beta, el glucagón, el riñón y el intestino.","Relacionar el mecanismo fisiopatológico con la elección del tratamiento.","Reconocer cuándo sospechar una diabetes tipo 1 o un tipo monogénico."],"conceptos":[{"icono":"Activity","termino":"Diabetes tipo 1","definicion":"Destrucción autoinmunitaria de la célula beta que lleva a deficiencia absoluta de insulina y requiere insulina desde el inicio."},{"icono":"Pill","termino":"Diabetes tipo 2","definicion":"Combinación variable de resistencia a la insulina y disfunción progresiva de la célula beta, con múltiples mecanismos metabólicos."},{"icono":"Droplets","termino":"Glucosa renal","definicion":"El riñón reabsorbe glucosa; los iSGLT2 bloquean ese transporte y aumentan la glucosuria."},{"icono":"Wheat","termino":"Incretinas","definicion":"GLP-1 y GIP son hormonas intestinales que estimulan la insulina y frenan el glucagón; los agonistas GLP-1 y tirzepatida actúan sobre ellas."}],"secciones":[{"titulo":"Tipo 1: falta insulina","parrafos":["La diabetes tipo 1 es una enfermedad autoinmunitaria en la que el sistema inmunitario destruye las células beta del páncreas. Aparece con mayor frecuencia en niños y adultos jóvenes, pero puede comenzar a cualquier edad. La deficiencia de insulina es absoluta: sin insulina exógena hay hiperglucemia, cetosis y riesgo de cetoacidosis. El tratamiento es insulina desde el diagnóstico, con educación intensiva y conteo de carbohidratos.","El inicio puede ser abrupto: poliuria, polidipsia, pérdida de peso, cansancio y visión borrosa. La presencia de cetonas y la ausencia de obesidad ayudan a sospechar, pero el diagnóstico definitivo es clínico y, en casos seleccionados, con autoanticuerpos. No se debe iniciar un tratamiento oral como sustituto de la insulina en diabetes tipo 1."]},{"titulo":"Tipo 2: resistencia y disfunción beta","parrafos":["En la diabetes tipo 2, la resistencia a la insulina en músculo, hígado y tejido adiposo hace que la célula beta tenga que producir más insulina. Durante años lo logra, pero la función beta declina de forma progresiva. El resultado es un aumento de la producción hepática de glucosa, menor captación periférica y alteración del efecto incretina, del glucagón y de la reabsorción renal de glucosa.","La obesidad, el sedentarismo, la genética y el ambiente contribuyen. El tratamiento no es solo “bajar la glucosa”: también busca reducir el riesgo cardiovascular, proteger el riñón, manejar el peso y prevenir hipoglucemias. Esa visión explica por qué los iSGLT2 y los agonistas GLP-1 ocupan un lugar central en pacientes con comorbilidad."]},{"titulo":"Otros tipos y gestacional","parrafos":["La diabetes gestacional aparece durante el embarazo y exige diagnóstico y tratamiento oportunos para reducir complicaciones maternas y fetales. Otros tipos incluyen diabetes monogénica (MODY), pancreatitis crónica, endocrinopatías, fibrosis quística y diabetes secundaria a medicamentos como los corticoides. La distinción importa porque el tratamiento y el pronóstico cambian.","Un adulto joven, delgado, con historia familiar fuerte y sin autoanticuerpos puede tener MODY. Un paciente con pancreatitis recurrente puede tener diabetes secundaria. Sospechar esos tipos evita años de tratamiento inadecuado y permite remitir a genética o a especializada cuando corresponde."]}],"errores":[{"error":"Asumir que todo adulto tiene diabetes tipo 2.","correccion":"La diabetes tipo 1 y los tipos monogénicos también aparecen en adultos. La pérdida de peso, las cetonas y la necesidad de insulina son señales de alarma."},{"error":"Tratar la diabetes tipo 1 con antidiabéticos orales.","correccion":"La diabetes tipo 1 requiere insulina desde el inicio; los orales no sustituyen la insulina."},{"error":"No buscar la causa en pacientes con pancreatitis o corticoides.","correccion":"La diabetes secundaria exige tratar la causa y ajustar el tratamiento."}],"comprueba":[{"pregunta":"¿Qué distingue la diabetes tipo 1 de la tipo 2?","respuesta":"La tipo 1 tiene deficiencia absoluta de insulina por destrucción autoinmunitaria; la tipo 2 combina resistencia a la insulina y disfunción beta progresiva."},{"pregunta":"¿Qué señales hacen sospechar diabetes tipo 1?","respuesta":"Inicio brusco, pérdida de peso, cetonas, sed intensa y necesidad de insulina."},{"pregunta":"¿Por qué importa clasificar bien la diabetes?","respuesta":"Porque el tratamiento, el riesgo de cetoacidosis y las complicaciones cambian según el tipo."}],"resumen":["La diabetes tipo 1 es **deficiencia absoluta de insulina**.","La tipo 2 combina **resistencia a la insulina y falla beta progresiva**.","La gestacional y las diabetes secundarias tienen **manejo específico**.","Clasificar bien evita tratamientos peligrosos o insuficientes."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"},{"cita":"Organización Mundial de la Salud. Diabetes: datos y cifras.","url":"https://www.who.int/es/news-room/fact-sheets/detail/diabetes"}],"imagenes":[{"ubicacion":"Después del gancho","descripcion":"Dos siluetas contrapuestas: un joven delgado con cetonas y una persona con obesidad central y hipertensión, unidas por un glucómetro.","alt":"Dos presentaciones clínicas distintas de diabetes"}],"keywords":["fisiopatología de la diabetes","diabetes tipo 1 vs tipo 2","diabetes tipo 2 resistencia a la insulina","diabetes gestacional","mody diabetes","clasificación de la diabetes","deficiencia de insulina","curso de diabetes para farmacéuticos"],"mapa":{"centro":"Fisiopatología de la diabetes","ramas":[{"titulo":"Célula beta","icono":"Activity","nodos":["Disfunción progresiva","Deficiencia relativa o absoluta","Insulina e incretinas"]},{"titulo":"Insulina","icono":"Syringe","nodos":["Resistencia hepática y muscular","Hiperinsulinemia compensadora","Glucosa no utilizada"]},{"titulo":"Hígado y grasa","icono":"Flame","nodos":["Gluconeogénesis","Lipólisis","Inflamación de bajo grado"]},{"titulo":"Riñón e intestino","icono":"Droplets","nodos":["Reabsorción de glucosa","Efecto incretina","Glucagón"]}]},"proceso":{"titulo":"Cómo orientar el tipo de diabetes en la consulta","intro":"","pasos":[{"titulo":"Edad y forma de inicio","detalle":"Inicio brusco, pérdida de peso y cetonas orientan a tipo 1; inicio gradual y obesidad, a tipo 2.","icono":"CalendarClock","evidencia":"Historia clínica."},{"titulo":"Antecedentes","detalle":"Enfermedad autoinmunitaria, pancreatitis, medicamentos, embarazo y historia familiar.","icono":"ClipboardList","evidencia":"Anamnesis."},{"titulo":"Laboratorio","detalle":"Glucosa, HbA1c, cetonas, función renal y, si hay duda, autoanticuerpos o péptido C.","icono":"TestTube","evidencia":"Resultados."},{"titulo":"Decisión terapéutica","detalle":"Tipo 1: insulina. Tipo 2: enfoque integral. Gestacional: manejo obstétrico.","icono":"Target","evidencia":"Plan documentado."},{"titulo":"Derivación","detalle":"Sospecha de tipo 1, MODY o diabetes secundaria: remitir al especialista.","icono":"Route","evidencia":"Remisión."}]},"caso":{"titulo":"El joven que adelgazó","contexto":"Andrés, 19 años, glucosa 420 mg/dL, HbA1c 12,8 %, cetonas positivas, IMC 20, sin antecedentes familiares. Refiere sed intensa y pérdida de 8 kg.","pregunta":"¿Cuál es la conducta más probable?","opciones":[{"texto":"Iniciar metformina y control en tres meses.","correcta":false,"retro":"La cetonuria y la pérdida de peso sugieren deficiencia de insulina. La metformina no trata la cetoacidosis ni la diabetes tipo 1."},{"texto":"Remitir de urgencia para evaluación de cetoacidosis e iniciar insulina.","correcta":true,"retro":"El cuadro es compatible con diabetes tipo 1 de debut. Requiere evaluación urgente, hidratación, insulina y educación."},{"texto":"Indicar solo cambios de alimentación.","correcta":false,"retro":"La hiperglucemia grave con cetonas no se maneja solo con dieta; hay riesgo de cetoacidosis."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Fisiopatología y clasificación de la diabetes: tipo 1, tipo 2 y otros tipos$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Fisiopatología y clasificación de la diabetes: tipo 1, tipo 2 y otros tipos$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 03. Criterios diagnósticos de diabetes y prediabetes, y tamizaje
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Una HbA1c de 6,2 % no es “normal”","texto":"Un hombre de 45 años con sobrepeso, padre con diabetes y presión de 138/88 mmHg recibe una HbA1c de 6,2 %. En la farmacia le dicen que “todavía no tiene diabetes” y que puede esperar. Es cierto que no cumple el criterio de diabetes, pero tiene prediabetes y un riesgo elevado. La intervención temprana puede retrasar la enfermedad y prevenir complicaciones."},"objetivos":["Aplicar los criterios diagnósticos de diabetes y prediabetes de la ADA 2026.","Identificar cuándo repetir una prueba y cuándo el diagnóstico es inequívoco.","Reconocer los factores de riesgo que justifican tamizaje.","Interpretar HbA1c, glucosa en ayunas y prueba de tolerancia oral."],"conceptos":[{"icono":"Target","termino":"HbA1c","definicion":"Promedio de glucosa de los últimos dos a tres meses. Un valor ≥6,5 % diagnostica diabetes; 5,7 a 6,4 % indica prediabetes."},{"icono":"Droplets","termino":"Glucosa en ayunas","definicion":"Glucosa medida tras al menos 8 horas de ayuno. ≥126 mg/dL en dos ocasiones o con síntomas diagnostica diabetes."},{"icono":"Timer","termino":"Prueba de tolerancia oral","definicion":"Glucosa a las 2 horas de una carga de 75 g. ≥200 mg/dL diagnostica diabetes; 140 a 199 mg/dL, intolerancia."},{"icono":"Search","termino":"Tamizaje","definicion":"Búsqueda de diabetes o prediabetes en personas asintomáticas con riesgo, para intervenir antes de las complicaciones."}],"secciones":[{"titulo":"Los cuatro criterios","parrafos":["La ADA acepta cuatro criterios para diagnosticar diabetes: HbA1c ≥6,5 %, glucosa en ayunas ≥126 mg/dL, glucosa a las 2 horas de una prueba de tolerancia oral ≥200 mg/dL, o glucosa aleatoria ≥200 mg/dL con síntomas clásicos. En ausencia de síntomas, el resultado debe confirmarse con una segunda prueba, preferiblemente la misma, en otra muestra.","La HbA1c puede ser engañosa en anemia, hemoglobinopatías, embarazo, enfermedad renal avanzada o después de una transfusión. En esos casos conviene usar glucosa en ayunas o prueba de tolerancia. La prueba de tolerancia es útil cuando la HbA1c y la glucosa en ayunas no coinciden o cuando se sospecha intolerancia a la glucosa."]},{"titulo":"Prediabetes: una ventana de oportunidad","parrafos":["La prediabetes se define por HbA1c de 5,7 a 6,4 %, glucosa en ayunas de 100 a 125 mg/dL o glucosa a las 2 horas de 140 a 199 mg/dL. No es una enfermedad benigna: aumenta el riesgo de progresar a diabetes y de eventos cardiovasculares. La intervención con cambios de estilo de vida y, en algunos casos, metformina, reduce la progresión.","El farmacéutico puede reforzar la importancia de la pérdida de peso moderada, la actividad física y la alimentación. También puede revisar si hay medicamentos que elevan la glucosa, como corticoides, antipsicóticos o algunos diuréticos, y si hay factores de riesgo cardiovascular que merecen tratamiento."]},{"titulo":"A quién tamizar","parrafos":["La ADA recomienda tamizar a todos los adultos desde los 35 años y a las personas con sobrepeso u obesidad que tengan uno o más factores de riesgo: antecedente familiar, hipertensión, dislipidemia, enfermedad cardiovascular, diabetes gestacional, síndrome de ovario poliquístico o pertenencia a grupos de alto riesgo. El tamizaje debe repetirse al menos cada tres años si es normal.","En personas con síntomas clásicos no se debe esperar el tamizaje: se mide la glucosa y se actúa. En el embarazo se usan criterios específicos y se tamiza entre las 24 y 28 semanas, o antes si hay factores de riesgo. El Químico Farmacéutico puede recordar estas indicaciones en la consulta y en la dispensación."]}],"errores":[{"error":"Diagnosticar diabetes con una sola prueba en un paciente asintomático.","correccion":"Confirmar con una segunda prueba, salvo que el cuadro sea inequívoco."},{"error":"Ignorar la prediabetes.","correccion":"Es una oportunidad para intervenir y prevenir la progresión."},{"error":"No considerar anemia o hemoglobinopatías al interpretar HbA1c.","correccion":"En esas condiciones usar glucosa en ayunas o prueba de tolerancia."}],"comprueba":[{"pregunta":"¿Cuáles son los criterios de diabetes?","respuesta":"HbA1c ≥6,5 %, ayunas ≥126 mg/dL, 2 h ≥200 mg/dL o glucosa aleatoria ≥200 mg/dL con síntomas."},{"pregunta":"¿Qué valores definen prediabetes?","respuesta":"HbA1c 5,7-6,4 %, ayunas 100-125 mg/dL o 2 h 140-199 mg/dL."},{"pregunta":"¿Cuándo se repite la prueba?","respuesta":"Cuando el paciente está asintomático y el resultado no es inequívoco."}],"resumen":["El diagnóstico requiere **criterios definidos** y, sin síntomas, confirmación.","La **prediabetes** es una oportunidad de prevención.","El tamizaje empieza a los **35 años** o antes con factores de riesgo.","La HbA1c tiene limitaciones en anemia, embarazo y enfermedad renal."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"Organización Mundial de la Salud. Diabetes: datos y cifras.","url":"https://www.who.int/es/news-room/fact-sheets/detail/diabetes"}],"imagenes":[{"ubicacion":"Sección de criterios","descripcion":"Tabla visual con cuatro pruebas y sus umbrales de normalidad, prediabetes y diabetes.","alt":"Criterios diagnósticos de diabetes y prediabetes"}],"keywords":["criterios diagnósticos de diabetes","prediabetes valores","hba1c 6.5","glucosa en ayunas 126","tamizaje de diabetes","prueba de tolerancia oral","diagnóstico de diabetes ada 2026","prediabetes tratamiento"],"mapa":{"centro":"Diagnóstico de diabetes","ramas":[{"titulo":"Criterios","icono":"Target","nodos":["HbA1c ≥6,5 %","Ayunas ≥126 mg/dL","2 h ≥200 mg/dL","Glucosa aleatoria ≥200 con síntomas"]},{"titulo":"Prediabetes","icono":"AlertTriangle","nodos":["HbA1c 5,7-6,4 %","Ayunas 100-125 mg/dL","2 h 140-199 mg/dL"]},{"titulo":"Confirmación","icono":"Repeat","nodos":["Repetir si no hay síntomas","Dos pruebas alteradas","Diagnóstico inequívoco con síntomas"]},{"titulo":"Tamizaje","icono":"Users","nodos":["Edad ≥35 años","Sobrepeso u obesidad","Antecedente familiar","Riesgo cardiovascular"]}]},"proceso":{"titulo":"Cómo interpretar una prueba de glucosa","intro":"","pasos":[{"titulo":"Verificar la muestra","detalle":"Confirmar ayuno, hora de la toma y condiciones de la prueba.","icono":"ClipboardCheck","evidencia":"Registro de la prueba."},{"titulo":"Comparar con el criterio","detalle":"Clasificar como normal, prediabetes o diabetes según el valor y la prueba.","icono":"Target","evidencia":"Resultado clasificado."},{"titulo":"Buscar síntomas","detalle":"Preguntar por sed, poliuria, pérdida de peso y visión borrosa.","icono":"Search","evidencia":"Anamnesis."},{"titulo":"Confirmar","detalle":"Repetir en otra muestra si no hay síntomas ni valores inequívocos.","icono":"Repeat","evidencia":"Segunda prueba."},{"titulo":"Actuar","detalle":"Educar, derivar y programar seguimiento según el resultado.","icono":"CalendarClock","evidencia":"Plan documentado."}]},"caso":{"titulo":"La HbA1c limítrofe","contexto":"Mujer de 52 años, IMC 31, madre con diabetes, HbA1c 6,1 % y glucosa en ayunas 112 mg/dL. No tiene síntomas.","pregunta":"¿Qué diagnóstico y conducta corresponden?","opciones":[{"texto":"Diabetes tipo 2; iniciar metformina de inmediato.","correcta":false,"retro":"Los valores están en rango de prediabetes, no de diabetes. La metformina puede considerarse en casos seleccionados, pero no es automática."},{"texto":"Prediabetes; intervención en estilo de vida, revisión de riesgo cardiovascular y seguimiento.","correcta":true,"retro":"HbA1c 6,1 % y ayunas 112 mg/dL corresponden a prediabetes. La prioridad es prevenir la progresión y evaluar el riesgo cardiometabólico."},{"texto":"Normal; no requiere seguimiento.","correcta":false,"retro":"Está en prediabetes y tiene factores de riesgo; requiere seguimiento y educación."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Criterios diagnósticos de diabetes y prediabetes, y tamizaje$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Criterios diagnósticos de diabetes y prediabetes, y tamizaje$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 04. Metas glucémicas individualizadas: HbA1c, tiempo en rango y metas de riesgo cardiovascular
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La meta que no es igual para todos","texto":"Dos personas con HbA1c de 8,2 % llegan a la farmacia. La primera tiene 42 años, diabetes reciente y ninguna complicación. La segunda tiene 82 años, enfermedad renal, dos hipoglucemias en el último mes y vive sola. La misma cifra no significa el mismo objetivo. Individualizar la meta evita tratar en exceso a quien no lo necesita y tratar en déficit a quien sí."},"objetivos":["Establecer metas de HbA1c individualizadas según edad, comorbilidad y riesgo de hipoglucemia.","Interpretar el tiempo en rango y los datos del monitoreo continuo.","Integrar metas de presión, lípidos y función renal en el seguimiento.","Reconocer los riesgos de la sobretratamiento y del infratratamiento."],"conceptos":[{"icono":"Target","termino":"HbA1c","definicion":"Promedio de glucosa de 2 a 3 meses. La meta general es <7 %, pero se ajusta según el paciente."},{"icono":"Timer","termino":"Tiempo en rango","definicion":"Porcentaje del día con glucosa entre 70 y 180 mg/dL. La meta habitual es >70 %, con <4 % por debajo de 70 y <1 % por debajo de 54."},{"icono":"AlertTriangle","termino":"Hipoglucemia","definicion":"Glucosa <70 mg/dL, con o sin síntomas. Es el principal límite para intensificar el tratamiento."},{"icono":"LineChart","termino":"Riesgo cardiovascular","definicion":"Probabilidad de infarto, ictus o muerte cardiovascular; se reduce con presión, lípidos, tabaco y fármacos con beneficio demostrado."}],"secciones":[{"titulo":"La HbA1c es un promedio, no toda la historia","parrafos":["La HbA1c informa el promedio de glucosa, pero no dice si el paciente tuvo hipoglucemias, hiperglucemias posprandiales o una gran variabilidad. Dos personas con la misma HbA1c pueden tener perfiles muy distintos. El monitoreo continuo de glucosa permite ver el tiempo en rango, el tiempo por debajo y por encima, y la variabilidad glucémica.","La meta general de HbA1c es <7 % para la mayoría de los adultos no embarazados. Se puede buscar <6,5 % si se logra sin hipoglucemia ni otros efectos adversos, y se acepta <8 % en personas con comorbilidad grave, esperanza de vida limitada, fragilidad o alto riesgo de hipoglucemia. La meta debe acordarse con el paciente y revisarse con el tiempo."]},{"titulo":"Tiempo en rango y monitoreo continuo","parrafos":["El tiempo en rango se define como el porcentaje de lecturas entre 70 y 180 mg/dL. La meta habitual es >70 %, con <4 % por debajo de 70 mg/dL y <1 % por debajo de 54 mg/dL. También se busca <25 % por encima de 180 mg/dL y <5 % por encima de 250 mg/dL. Estos objetivos son especialmente útiles en diabetes tipo 1 y en personas con insulina.","El reporte AGP muestra patrones por hora del día, lo que ayuda a ajustar insulina, alimentación y actividad. El Químico Farmacéutico puede enseñar a leerlo, identificar hipoglucemias nocturnas y detectar errores de técnica. No se trata solo de “bajar la glucosa”, sino de lograr un patrón seguro y estable."]},{"titulo":"Metas que van más allá de la glucosa","parrafos":["La diabetes es un factor de riesgo cardiovascular y renal. El seguimiento debe incluir presión arterial, LDL, función renal, albuminuria, peso, tabaco y vacunación. En muchos pacientes, el beneficio de un iSGLT2 o un agonista GLP-1 sobre el corazón y el riñón es independiente de la HbA1c. La meta glucémica no debe hacer olvidar esos objetivos.","La individualización también considera el riesgo de hipoglucemia, las caídas, la carga de pastillas, el costo y la preferencia del paciente. Un esquema que logra una HbA1c perfecta pero produce hipoglucemias diarias no es un buen tratamiento. La meta es una vida más segura y sostenible, no una cifra aislada."]}],"errores":[{"error":"Aplicar <7 % a todos los pacientes.","correccion":"La meta depende de la edad, la comorbilidad, la fragilidad y el riesgo de hipoglucemia."},{"error":"Mirar solo la HbA1c e ignorar el tiempo en rango.","correccion":"El tiempo en rango y las hipoglucias muestran lo que el promedio oculta."},{"error":"Intensificar el tratamiento sin revisar la adherencia y la técnica.","correccion":"Antes de subir dosis, confirmar que el paciente toma y aplica bien el medicamento."}],"comprueba":[{"pregunta":"¿Cuál es la meta general de HbA1c?","respuesta":"<7 % para la mayoría de los adultos, con ajustes individuales."},{"pregunta":"¿Qué es el tiempo en rango?","respuesta":"El porcentaje de tiempo con glucosa entre 70 y 180 mg/dL; la meta habitual es >70 %."},{"pregunta":"¿Cuándo se acepta una meta menos estricta?","respuesta":"En edad avanzada, fragilidad, comorbilidad grave, esperanza de vida limitada o alto riesgo de hipoglucemia."}],"resumen":["La meta de HbA1c es **individualizada**, no universal.","El **tiempo en rango** completa la información del promedio.","La seguridad y la calidad de vida pesan tanto como la cifra.","La meta glucémica se integra con presión, lípidos, riñón y corazón."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"}],"imagenes":[{"ubicacion":"Sección de metas","descripcion":"Pirámide de metas de HbA1c con tres niveles: estricta, habitual y flexible, y ejemplos de pacientes.","alt":"Metas de HbA1c individualizadas en diabetes"}],"keywords":["meta de hba1c","tiempo en rango diabetes","metas glucémicas individualizadas","hba1c 7 por ciento","hipoglucemia diabetes","monitoreo continuo de glucosa","ada 2026 metas","diabetes en adultos mayores"],"mapa":{"centro":"Meta individualizada","ramas":[{"titulo":"Más estricta","icono":"Target","nodos":["Joven","Diabetes reciente","Sin hipoglucemia","Buena adherencia"]},{"titulo":"Menos estricta","icono":"AlertTriangle","nodos":["Edad avanzada","Comorbilidad grave","Hipoglucemias","Fragilidad"]},{"titulo":"Más allá de HbA1c","icono":"Activity","nodos":["Tiempo en rango","Variabilidad","Peso","Presión y lípidos"]},{"titulo":"Riesgo","icono":"ShieldCheck","nodos":["Cardiovascular","Renal","Hipoglucemia","Caídas"]}]},"proceso":{"titulo":"Cómo acordar una meta glucémica","intro":"","pasos":[{"titulo":"Evaluar el perfil","detalle":"Edad, comorbilidades, fragilidad, esperanza de vida, riesgo de hipoglucemia y preferencias.","icono":"Users","evidencia":"Evaluación documentada."},{"titulo":"Revisar el control","detalle":"HbA1c, tiempo en rango, glucometrías y eventos de hipoglucemia.","icono":"LineChart","evidencia":"Reporte glucémico."},{"titulo":"Definir la meta","detalle":"HbA1c <7 % general; <6,5 % si es seguro; <8 % en pacientes de alto riesgo.","icono":"Target","evidencia":"Meta acordada."},{"titulo":"Alinear el tratamiento","detalle":"Elegir fármacos que logren la meta sin hipoglucemia ni carga excesiva.","icono":"Pill","evidencia":"Plan ajustado."},{"titulo":"Revisar","detalle":"Evaluar en 3 a 6 meses y ajustar según la evolución.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"La meta de doña Carmen","contexto":"Carmen tiene 82 años, diabetes de 20 años, TFG de 32 ml/min, dos hipoglucemias sintomáticas en el último mes y vive sola. Su HbA1c es 7,8 %.","pregunta":"¿Cuál es la meta más razonable?","opciones":[{"texto":"HbA1c <6,5 % para prevenir complicaciones.","correcta":false,"retro":"En una persona mayor, con enfermedad renal y hipoglucemias, una meta tan estricta aumenta el riesgo de caídas, confusión y eventos graves."},{"texto":"HbA1c <8 % y evitar hipoglucemias, revisando el esquema que las causa.","correcta":true,"retro":"La meta menos estricta es apropiada en fragilidad y alto riesgo de hipoglucemia. Lo prioritario es la seguridad y la calidad de vida."},{"texto":"Suspender todo tratamiento y no volver a medir.","correcta":false,"retro":"La diabetes no tratada también causa daño. Se ajusta el esquema, no se abandona."}]}}$j$::jsonb;
