  END IF;

  -- 07. Introducción a la unidad: antidiabéticos orales clásicos y su lugar en 2026
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La caja vieja que sigue funcionando","texto":"En una droguería de Barranquilla, un paciente pide “la metformina de siempre” porque es lo único que su EPS cubre sin trámite. En otra farmacia, una paciente con insuficiencia cardíaca recibe un iSGLT2 y pregunta por qué ya no le dan metformina. Los antidiabéticos orales clásicos siguen siendo importantes, pero su lugar cambió: no son una receta única, sino opciones dentro de un algoritmo que mira el corazón, el riñón, el peso y el riesgo de hipoglucemia."},"objetivos":["Clasificar los antidiabéticos orales clásicos y sus mecanismos.","Reconocer el lugar de la metformina, los iDPP-4, las sulfonilureas y la pioglitazona en 2026.","Identificar los criterios que hacen preferir o evitar cada grupo.","Diseñar una combinación inicial razonable según el perfil del paciente."],"conceptos":[{"icono":"Pill","termino":"Metformina","definicion":"Biguanida que reduce la producción hepática de glucosa y mejora la sensibilidad; no causa hipoglucemia por sí sola."},{"icono":"Activity","termino":"iDPP-4","definicion":"Inhibidores de la dipeptidil peptidasa-4 que aumentan la incretina endógena; peso neutro y bajo riesgo de hipoglucemia."},{"icono":"Zap","termino":"Sulfonilureas","definicion":"Estimulan la secreción de insulina; son eficaces y económicas, pero causan hipoglucemia y aumento de peso."},{"icono":"Scale","termino":"Pioglitazona","definicion":"Agonista de PPARγ que mejora la sensibilidad a la insulina; útil en hígado graso, pero causa retención de líquidos y aumento de peso."}],"secciones":[{"titulo":"Qué sigue vigente","parrafos":["La metformina sigue siendo uno de los fármacos más usados por su eficacia, seguridad, bajo costo y amplia experiencia. No suele causar hipoglucemia y tiene un efecto neutro sobre el peso. Sin embargo, no debe usarse en insuficiencia renal avanzada ni en situaciones de acidosis, y su tolerancia digestiva puede limitar la adherencia. Su lugar en 2026 es el de un fármaco útil, pero no obligatorio antes de un iSGLT2 o un GLP-1 cuando hay indicación cardiorrenal.","Los iDPP-4 son una opción bien tolerada, con peso neutro y bajo riesgo de hipoglucemia. Son útiles en adultos mayores, en personas con riesgo de hipoglucemia o cuando se busca una opción oral sencilla. Su efecto sobre la HbA1c es modesto y no tienen beneficio cardiovascular o renal demostrado de forma consistente."]},{"titulo":"Qué debe usarse con cuidado","parrafos":["Las sulfonilureas son eficaces y económicas, pero producen hipoglucemia, sobre todo en adultos mayores, insuficiencia renal, bajo peso o falta de adherencia a las comidas. La glibenclamida tiene mayor riesgo de hipoglucemia prolongada. La pioglitazona mejora la sensibilidad y puede ser útil en hígado graso, pero causa retención de líquidos, aumento de peso y no se recomienda en insuficiencia cardíaca.","La elección depende del paciente: un adulto joven con bajo riesgo de hipoglucemia y pocos recursos puede beneficiarse de una sulfonilurea; una persona mayor con TFG baja y riesgo de caídas probablemente no. La pioglitazona no es un fármaco de primera línea en insuficiencia cardíaca ni en osteoporosis avanzada."]},{"titulo":"Cómo combinarlos","parrafos":["Las combinaciones deben buscar mecanismos complementarios y evitar efectos adversos aditivos. Metformina con iDPP-4 es una opción oral bien tolerada. Metformina con sulfonilurea es eficaz y económica, pero exige vigilancia de hipoglucemia. La triple terapia oral puede ser útil, aunque aumenta la carga de pastillas y el riesgo de efectos adversos.","Si la HbA1c está lejos de la meta o hay síntomas, la combinación con un fármaco inyectable o insulina puede ser más eficaz que sumar un tercer oral. La decisión debe ser individualizada y revisada en 3 a 6 meses."]}],"errores":[{"error":"Creer que los orales clásicos son obsoletos.","correccion":"Siguen siendo útiles en pacientes seleccionados, sobre todo por costo y accesibilidad."},{"error":"Usar sulfonilureas sin revisar el riesgo de hipoglucemia.","correccion":"En adultos mayores, TFG baja o comidas irregulares, el riesgo es alto."},{"error":"Combinar fármacos sin revisar efectos adversos aditivos.","correccion":"Evitar combinaciones que sumen hipoglucemia, retención de líquidos o molestias digestivas."}],"comprueba":[{"pregunta":"¿Cuál es el principal riesgo de las sulfonilureas?","respuesta":"La hipoglucemia, especialmente en adultos mayores y en insuficiencia renal."},{"pregunta":"¿Qué ventaja tienen los iDPP-4?","respuesta":"Peso neutro y bajo riesgo de hipoglucemia, con buena tolerancia."},{"pregunta":"¿Cuándo se evita la pioglitazona?","respuesta":"En insuficiencia cardíaca, retención de líquidos y osteoporosis avanzada."}],"resumen":["Los orales clásicos siguen vigentes, pero **no son universales**.","La metformina es útil; las sulfonilureas exigen vigilancia de hipoglucemia.","Los iDPP-4 son seguros y bien tolerados, con efecto modesto.","La combinación se elige por **mecanismo y seguridad**."],"referencias":[{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"},{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"},{"cita":"AEMPS-CIMA. Ficha técnica de Sitagliptina Cinfamed 100 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/86323/FT_86323.html"}],"imagenes":[{"ubicacion":"Sección de clasificación","descripcion":"Cuatro frascos rotulados (metformina, iDPP-4, sulfonilurea y pioglitazona) con iconos de hígado, incretina, insulina y sensibilidad.","alt":"Antidiabéticos orales clásicos y sus mecanismos"}],"keywords":["antidiabéticos orales","metformina 2026","idpp-4","sulfonilureas hipoglucemia","pioglitazona","tratamiento diabetes tipo 2 oral","combinación antidiabética","curso farmacoterapia diabetes"],"mapa":{"centro":"Orales clásicos","ramas":[{"titulo":"Metformina","icono":"Pill","nodos":["Hígado","Peso neutro","Función renal"]},{"titulo":"iDPP-4","icono":"Activity","nodos":["Incretinas","Bajo riesgo de hipoglucemia","Poblaciones especiales"]},{"titulo":"Sulfonilureas","icono":"Zap","nodos":["Secreción de insulina","Hipoglucemia","Costo"]},{"titulo":"Pioglitazona","icono":"Scale","nodos":["Sensibilidad","Retención de líquidos","Hígado graso"]}]},"proceso":{"titulo":"Cómo elegir un oral clásico","intro":"","pasos":[{"titulo":"Definir la meta","detalle":"HbA1c, peso, riesgo de hipoglucemia y comorbilidad.","icono":"Target","evidencia":"Meta acordada."},{"titulo":"Revisar la función renal","detalle":"TFG para metformina y ajustes de otros fármacos.","icono":"Droplets","evidencia":"TFG documentada."},{"titulo":"Evaluar el riesgo","detalle":"Hipoglucemia, insuficiencia cardíaca, hígado graso y peso.","icono":"ShieldCheck","evidencia":"Evaluación de riesgo."},{"titulo":"Elegir y combinar","detalle":"Seleccionar el fármaco y la combinación con mecanismos complementarios.","icono":"Pill","evidencia":"Plan terapéutico."},{"titulo":"Seguir","detalle":"Revisar HbA1c, tolerancia, adherencia y eventos adversos.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"El adulto mayor con hipoglucemias","contexto":"Mujer de 78 años, diabetes de 12 años, TFG 45 ml/min, HbA1c 7,4 %, dos episodios de sudoración y temblor en el último mes. Toma metformina 850 mg cada 12 horas y glibenclamida 5 mg al día.","pregunta":"¿Qué revisión es prioritaria?","opciones":[{"texto":"Aumentar la metformina para bajar la HbA1c.","correcta":false,"retro":"La paciente ya tiene hipoglucemias y TFG reducida. Aumentar metformina no aborda el riesgo y puede empeorar la tolerancia digestiva."},{"texto":"Revisar la glibenclamida, que probablemente causa las hipoglucemias, y proponer al médico una alternativa con menor riesgo.","correcta":true,"retro":"Las sulfonilureas son una causa frecuente de hipoglucemia en adultos mayores con enfermedad renal. La intervención debe priorizar la seguridad."},{"texto":"Suspender todo tratamiento sin consultar.","correcta":false,"retro":"La diabetes requiere tratamiento; se ajusta el esquema, no se abandona."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: antidiabéticos orales clásicos y su lugar en 2026$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Introducción a la unidad: antidiabéticos orales clásicos y su lugar en 2026$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 08. Metformina: mecanismo, indicaciones, dosificación y ajuste por función renal
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La metformina que casi se suspende por una creatinina","texto":"Un paciente de 70 años llega con creatinina de 1,4 mg/dL y la farmacia le dice que “ya no puede tomar metformina porque tiene el riñón dañado”. En realidad, la creatinina aislada no basta: hay que estimar la TFG, revisar la dosis, la evolución y el riesgo de acidosis. Suspender un fármaco útil por una interpretación incompleta también es un error de seguridad."},"objetivos":["Explicar el mecanismo de la metformina y sus efectos metabólicos.","Aplicar la dosificación y el ajuste por función renal.","Reconocer las situaciones en las que se suspende temporal o definitivamente.","Diseñar un plan de inicio y titulación para mejorar la tolerancia."],"conceptos":[{"icono":"Pill","termino":"Biguanida","definicion":"Familia de la metformina; reduce la gluconeogénesis hepática y mejora la sensibilidad periférica sin estimular la insulina."},{"icono":"Droplets","termino":"TFG estimada","definicion":"Medida de la función renal que se usa para ajustar la metformina. No se debe usar solo la creatinina sérica."},{"icono":"AlertTriangle","termino":"Acidosis láctica","definicion":"Complicación rara pero grave de la metformina, favorecida por insuficiencia renal, hipoxia, sepsis, alcohol o contraste."},{"icono":"CalendarClock","termino":"Titulación","definicion":"Aumento gradual de la dosis para reducir los síntomas digestivos y mejorar la adherencia."}],"secciones":[{"titulo":"Cómo actúa","parrafos":["La metformina reduce la producción hepática de glucosa, sobre todo la gluconeogénesis, y mejora la sensibilidad a la insulina en músculo y tejido adiposo. No estimula la secreción de insulina, por eso no causa hipoglucemia cuando se usa sola. También puede reducir la absorción intestinal de glucosa y favorecer un perfil lipídico más favorable.","Su efecto sobre la HbA1c es de aproximadamente 1 a 1,5 puntos porcentuales, variable según la dosis y el paciente. Es un fármaco útil, económico y con décadas de experiencia. No produce aumento de peso y puede tener un efecto neutro o ligeramente favorable sobre el peso."]},{"titulo":"Dosis y titulación","parrafos":["Se inicia con 500 mg una o dos veces al día con las comidas, y se aumenta cada una o dos semanas según tolerancia y glucosa. La dosis habitual es de 1.000 a 2.000 mg al día, con un máximo de 2.550 mg en algunas formulaciones. La presentación de liberación prolongada puede mejorar la tolerancia digestiva y permitir una toma única.","La titulación lenta reduce la diarrea y las náuseas. Si los síntomas persisten, se puede reducir la dosis o cambiar a liberación prolongada. La adherencia mejora cuando se explica que los efectos digestivos suelen disminuir con el tiempo y que la toma con comida es importante."]},{"titulo":"Ajuste por función renal","parrafos":["La metformina se elimina por el riñón. Con TFG ≥60 ml/min no requiere ajuste. Con TFG de 45 a 59 ml/min se revisa la dosis y el riesgo. Con TFG de 30 a 44 ml/min no se recomienda iniciar y, si ya está en uso, se reduce la dosis y se vigila estrechamente. Con TFG <30 ml/min está contraindicada. La creatinina aislada no es suficiente; se debe estimar la TFG.","Se suspende temporalmente antes de un estudio con contraste yodado o de una cirugía mayor, y se reinicia cuando la función renal se confirma estable. También se suspende en sepsis, deshidratación, hipoxia o insuficiencia cardíaca descompensada, porque aumentan el riesgo de acidosis láctica."]}],"errores":[{"error":"Suspender metformina solo por una creatinina elevada.","correccion":"Calcular la TFG y evaluar el contexto antes de decidir."},{"error":"Iniciar con dosis altas.","correccion":"La titulación gradual mejora la tolerancia y la adherencia."},{"error":"No suspender antes de contraste o cirugía.","correccion":"La suspensión temporal reduce el riesgo de acidosis láctica."}],"comprueba":[{"pregunta":"¿Por qué la metformina no causa hipoglucemia sola?","respuesta":"Porque no estimula la secreción de insulina; reduce la producción hepática y mejora la sensibilidad."},{"pregunta":"¿Qué TFG contraindica la metformina?","respuesta":"TFG <30 ml/min."},{"pregunta":"¿Cuándo se suspende temporalmente?","respuesta":"Antes de contraste yodado, cirugía mayor, sepsis, deshidratación o hipoxia."}],"resumen":["La metformina reduce la **gluconeogénesis** y mejora la sensibilidad.","Se titula lento para tolerar los efectos digestivos.","La **TFG** guía el ajuste y la suspensión.","No causa hipoglucemia por sí sola, pero puede causar acidosis láctica en riesgo."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de ajuste renal","descripcion":"Semáforo de TFG con tres colores y dosis de metformina correspondientes.","alt":"Ajuste de metformina según la función renal"}],"keywords":["metformina mecanismo de acción","metformina dosis","metformina función renal","metformina tfg 30","metformina acidosis láctica","metformina titulación","metformina antes de contraste","curso metformina diabetes"],"mapa":{"centro":"Metformina","ramas":[{"titulo":"Mecanismo","icono":"Pill","nodos":["Menos gluconeogénesis","Más sensibilidad","Sin hipoglucemia"]},{"titulo":"Inicio","icono":"CalendarClock","nodos":["500 mg con comida","Aumento gradual","Tolerancia digestiva"]},{"titulo":"Riñón","icono":"Droplets","nodos":["TFG 45-59: revisar","TFG 30-44: no iniciar","TFG <30: contraindicada"]},{"titulo":"Suspensión","icono":"AlertTriangle","nodos":["Contraste","Cirugía","Sepsis o hipoxia"]}]},"proceso":{"titulo":"Cómo iniciar metformina de forma segura","intro":"","pasos":[{"titulo":"Confirmar indicación","detalle":"Diabetes tipo 2, prediabetes seleccionada o síndrome de ovario poliquístico, según el caso.","icono":"Target","evidencia":"Indicación documentada."},{"titulo":"Calcular TFG","detalle":"Usar creatinina y edad; no basarse solo en la creatinina.","icono":"Calculator","evidencia":"TFG registrada."},{"titulo":"Iniciar bajo","detalle":"500 mg con la comida y aumentar según tolerancia.","icono":"Pill","evidencia":"Dosis inicial."},{"titulo":"Educar","detalle":"Explicar síntomas digestivos, B12, alcohol y suspensión antes de contraste.","icono":"Users","evidencia":"Educación documentada."},{"titulo":"Revisar","detalle":"HbA1c, tolerancia y TFG al menos anual.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"TFG de 38 ml/min","contexto":"Hombre de 74 años, diabetes tipo 2, TFG 38 ml/min, HbA1c 7,6 %, toma metformina 1 g cada 12 horas. No tiene síntomas digestivos ni acidosis.","pregunta":"¿Qué hacer con la metformina?","opciones":[{"texto":"Mantener la misma dosis porque la HbA1c está cerca de la meta.","correcta":false,"retro":"Con TFG 30-44 ml/min no se recomienda mantener dosis altas; se debe revisar y reducir, con vigilancia."},{"texto":"Revisar con el médico la reducción de la dosis o el cambio de esquema, y vigilar TFG y síntomas.","correcta":true,"retro":"La TFG obliga a ajustar. La metformina puede continuar en dosis menor si se justifica, con seguimiento estrecho."},{"texto":"Suspender de inmediato y no avisar al médico.","correcta":false,"retro":"La suspensión puede ser necesaria, pero debe coordinarse y acompañarse de una alternativa."}]}}$j$::jsonb;
