  -- 09. Seguridad de la metformina: efectos digestivos, vitamina B12, acidosis láctica, contraste y cirugía
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La diarrea que hizo abandonar el tratamiento","texto":"Una paciente de 61 años abandonó la metformina a la semana porque tenía diarrea y náuseas. Nunca le explicaron que los síntomas suelen mejorar si se empieza con dosis baja y se toma con comida. Meses después llegó con HbA1c de 9,2 %. La intolerancia digestiva es la causa más frecuente de abandono, y muchas veces se puede prevenir con educación y titulación."},"objetivos":["Prevenir y manejar los efectos digestivos de la metformina.","Reconocer el riesgo de déficit de vitamina B12 y cuándo medirla.","Identificar los factores que aumentan el riesgo de acidosis láctica.","Aplicar las reglas de suspensión antes de contraste, cirugía y enfermedad aguda."],"conceptos":[{"icono":"AlertTriangle","termino":"Intolerancia digestiva","definicion":"Diarrea, náuseas, dolor abdominal o sabor metálico; es la causa más frecuente de abandono de la metformina."},{"icono":"Droplets","termino":"Vitamina B12","definicion":"La metformina puede reducir su absorción con el uso prolongado y causar anemia o neuropatía."},{"icono":"Flame","termino":"Acidosis láctica","definicion":"Acumulación de lactato por hipoperfusión, hipoxia o falla renal; es rara pero grave."},{"icono":"ShieldCheck","termino":"Reglas de días de enfermedad","definicion":"Suspender metformina durante vómito, diarrea, fiebre alta, deshidratación o mala ingesta, y reiniciar al recuperarse."}],"secciones":[{"titulo":"Efectos digestivos","parrafos":["La diarrea, las náuseas, el dolor abdominal y el sabor metálico son frecuentes al inicio. Suelen mejorar con la titulación gradual y la toma con alimentos. La formulación de liberación prolongada puede reducir la intolerancia. Si los síntomas son intensos o persistentes, se reduce la dosis o se cambia de presentación; no se debe abandonar sin alternativa.","La educación anticipatoria es clave: explicar que los síntomas suelen ser transitorios, que se debe empezar con dosis baja y que la toma con comida reduce el malestar. Si hay deshidratación por diarrea, se suspende temporalmente y se reinicia cuando el paciente esté estable."]},{"titulo":"Vitamina B12","parrafos":["El uso prolongado de metformina se asocia con déficit de vitamina B12, sobre todo en personas mayores, vegetarianas o con anemia. El déficit puede causar anemia macrocítica, neuropatía periférica y síntomas cognitivos. La ADA recomienda medir B12 de forma periódica en pacientes con factores de riesgo o síntomas.","El Químico Farmacéutico puede preguntar por hormigueo, debilidad, palidez o fatiga y revisar el hemograma. Si se detecta déficit, se deriva para tratamiento y seguimiento. No se debe atribuir toda neuropatía a la diabetes sin descartar otras causas."]},{"titulo":"Acidosis láctica y situaciones de riesgo","parrafos":["La acidosis láctica es rara, pero grave. Se favorece por insuficiencia renal, sepsis, hipoxia, insuficiencia cardíaca descompensada, alcoholismo, deshidratación y contraste yodado. Los síntomas incluyen malestar, dolor abdominal, respiración rápida, somnolencia y acidosis metabólica. Ante la sospecha, se suspende la metformina y se busca atención urgente.","Antes de un estudio con contraste se suspende la metformina y se reinicia cuando la función renal se confirma estable, según el protocolo. Antes de cirugía mayor también se suspende. En enfermedad aguda con vómito, diarrea o mala ingesta, se aplican las reglas de días de enfermedad."]}],"errores":[{"error":"Abandonar la metformina por diarrea sin probar titulación.","correccion":"La dosis baja, la toma con comida y la liberación prolongada pueden mejorar la tolerancia."},{"error":"No medir B12 en uso prolongado.","correccion":"El déficit puede causar anemia y neuropatía; se debe buscar en pacientes de riesgo."},{"error":"Mantener metformina durante contraste o sepsis.","correccion":"Se suspende temporalmente para prevenir acidosis láctica."}],"comprueba":[{"pregunta":"¿Cómo se reducen los efectos digestivos?","respuesta":"Iniciando con dosis baja, tomando con comida y titulando lentamente."},{"pregunta":"¿Qué déficit puede causar la metformina a largo plazo?","respuesta":"Déficit de vitamina B12."},{"pregunta":"¿Cuándo se suspende la metformina?","respuesta":"Antes de contraste, cirugía mayor, sepsis, deshidratación, hipoxia o enfermedad aguda con mala ingesta."}],"resumen":["La **titulación** previene la intolerancia digestiva.","La **B12** se vigila en uso prolongado y grupos de riesgo.","La acidosis láctica es rara pero grave; se previene con reglas de suspensión.","Las **reglas de días de enfermedad** son parte de la educación."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Metformina Cinfa 850 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/68167/FT_68167.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de seguridad","descripcion":"Infografía con cuatro señales de alarma y las reglas de suspensión de metformina.","alt":"Seguridad y reglas de suspensión de la metformina"}],"keywords":["metformina efectos secundarios","metformina diarrea","metformina vitamina b12","metformina acidosis láctica","metformina contraste","metformina cirugía","reglas de días de enfermedad diabetes","metformina seguridad"],"mapa":{"centro":"Seguridad de la metformina","ramas":[{"titulo":"Digestivo","icono":"AlertTriangle","nodos":["Diarrea","Náuseas","Titulación lenta"]},{"titulo":"B12","icono":"Droplets","nodos":["Uso prolongado","Anemia","Neuropatía"]},{"titulo":"Láctico","icono":"Flame","nodos":["TFG baja","Sepsis","Hipoxia"]},{"titulo":"Suspensión","icono":"ShieldCheck","nodos":["Contraste","Cirugía","Enfermedad aguda"]}]},"proceso":{"titulo":"Reglas de seguridad con metformina","intro":"","pasos":[{"titulo":"Iniciar bajo","detalle":"500 mg con comida y aumentar según tolerancia.","icono":"Pill","evidencia":"Dosis inicial."},{"titulo":"Anticipar síntomas","detalle":"Explicar diarrea, náuseas y sabor metálico; cómo manejarlos.","icono":"Users","evidencia":"Educación."},{"titulo":"Revisar B12","detalle":"En uso prolongado, anemia o neuropatía.","icono":"Droplets","evidencia":"Resultado de B12."},{"titulo":"Suspender en riesgo","detalle":"Contraste, cirugía, sepsis, deshidratación o hipoxia.","icono":"AlertTriangle","evidencia":"Indicación registrada."},{"titulo":"Reiniciar","detalle":"Cuando la función renal y el estado clínico sean estables.","icono":"CheckCircle2","evidencia":"Reinicio documentado."}]},"caso":{"titulo":"Vómito y diarrea en un paciente con metformina","contexto":"Mujer de 68 años, diabetes tipo 2, TFG 52 ml/min, toma metformina 1 g cada 12 horas. Tiene gastroenteritis con vómito y no tolera líquidos.","pregunta":"¿Qué conducta es más segura?","opciones":[{"texto":"Continuar la metformina porque la TFG es mayor de 30.","correcta":false,"retro":"La deshidratación y la mala ingesta aumentan el riesgo de acidosis láctica. Se suspende temporalmente."},{"texto":"Suspender la metformina durante la enfermedad aguda, hidratar y reiniciar cuando se recupere y la función renal sea estable.","correcta":true,"retro":"Las reglas de días de enfermedad indican suspender en vómito, diarrea o mala ingesta, y reiniciar al recuperarse."},{"texto":"Aumentar la dosis para compensar la glucosa.","correcta":false,"retro":"Aumentar la dosis durante una enfermedad aguda es peligroso."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Seguridad de la metformina: efectos digestivos, vitamina B12, acidosis láctica, contraste y cirugía$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Seguridad de la metformina: efectos digestivos, vitamina B12, acidosis láctica, contraste y cirugía$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 10. Inhibidores de la DPP-4: mecanismo, perfil de seguridad y uso en poblaciones especiales
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La opción oral para quien no puede fallar","texto":"Un paciente de 80 años, con TFG de 35 ml/min, vive solo y tiene riesgo de hipoglucemia. Necesita un fármaco oral sencillo, con bajo riesgo de hipoglucemia y buena tolerancia. Los iDPP-4 pueden encajar, pero no son iguales entre sí: algunos requieren ajuste renal, otros no, y su efecto sobre la glucosa es modesto. Elegir bien exige conocer sus diferencias."},"objetivos":["Explicar el mecanismo de los iDPP-4 y su efecto incretina.","Comparar sitagliptina, linagliptin, saxagliptin y alogliptin.","Aplicar el ajuste renal y reconocer las señales de seguridad.","Identificar al paciente en quien un iDPP-4 es una buena opción."],"conceptos":[{"icono":"Activity","termino":"DPP-4","definicion":"Enzima que degrada GLP-1 y GIP. Su inhibición prolonga la acción de las incretinas endógenas."},{"icono":"Pill","termino":"Sitagliptina","definicion":"iDPP-4 de una vez al día; requiere ajuste en insuficiencia renal moderada o grave."},{"icono":"ShieldCheck","termino":"Linagliptina","definicion":"iDPP-4 que se elimina por vía biliar y no requiere ajuste renal."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Riesgo bajo de hipoglucemia; se vigilan pancreatitis, artralgias, penfigoide y, con saxagliptina, insuficiencia cardíaca."}],"secciones":[{"titulo":"Cómo actúan","parrafos":["Las incretinas GLP-1 y GIP se liberan después de comer y estimulan la insulina, frenan el glucagón y enlentecen el vaciamiento gástrico. La DPP-4 las degrada rápidamente. Los iDPP-4 prolongan su acción endógena, pero no sustituyen la deficiencia de incretinas como los agonistas GLP-1. Su efecto sobre la HbA1c es modesto, de aproximadamente 0,5 a 0,8 puntos porcentuales.","Como su efecto sobre la insulina depende de la glucosa, el riesgo de hipoglucemia es bajo cuando se usan solos. Son peso neutros y bien tolerados. No producen el efecto de saciedad ni la pérdida de peso de los agonistas GLP-1."]},{"titulo":"Diferencias entre fármacos","parrafos":["La sitagliptina se administra una vez al día y requiere ajuste en insuficiencia renal moderada o grave. La linagliptina no requiere ajuste renal, lo que la hace útil en enfermedad renal avanzada. La saxagliptina se ajusta en insuficiencia renal y se ha asociado con un aumento de hospitalizaciones por insuficiencia cardíaca, por lo que se evita en esos pacientes. El alogliptin también requiere ajuste renal.","La elección depende de la TFG, la comorbilidad cardíaca, el costo y la cobertura. En un paciente con insuficiencia cardíaca, se prefiere evitar saxagliptina. En enfermedad renal avanzada, linagliptina es una opción sencilla. En todos los casos, el efecto glucémico es modesto y puede requerir combinación."]},{"titulo":"Seguridad y poblaciones especiales","parrafos":["Los iDPP-4 son bien tolerados, pero se han descrito pancreatitis aguda, artralgias intensas y penfigoide bulloso. Ante dolor abdominal persistente, se suspende y se evalúa. En adultos mayores y en personas con riesgo de hipoglucemia son una opción atractiva, siempre que la meta glucémica sea alcanzable.","No se recomiendan como sustitutos de un agonista GLP-1 cuando el objetivo es pérdida de peso o beneficio cardiovascular. En insuficiencia cardíaca, se prefiere un iSGLT2. En enfermedad renal, linagliptina puede usarse sin ajuste, pero no reemplaza la nefroprotección con iSGLT2 cuando está indicada."]}],"errores":[{"error":"Esperar una gran reducción de HbA1c con un iDPP-4.","correccion":"Su efecto es modesto; si la meta está lejos, se necesita combinación o un fármaco con mayor potencia."},{"error":"Usar saxagliptina en insuficiencia cardíaca.","correccion":"Se asocia con hospitalizaciones por insuficiencia cardíaca; se prefiere evitarla."},{"error":"Olvidar el ajuste renal de sitagliptina y alogliptin.","correccion":"Revisar la TFG y ajustar según la ficha técnica."}],"comprueba":[{"pregunta":"¿Cuál es el efecto de los iDPP-4 sobre el peso?","respuesta":"Neutro."},{"pregunta":"¿Qué iDPP-4 no requiere ajuste renal?","respuesta":"Linagliptina."},{"pregunta":"¿Qué efecto adverso raro se debe vigilar?","respuesta":"Pancreatitis, artralgias y penfigoide bulloso."}],"resumen":["Los iDPP-4 prolongan la acción de las **incretinas endógenas**.","Su efecto es **modesto**, con peso neutro y bajo riesgo de hipoglucemia.","La **TFG** y la insuficiencia cardíaca guían la elección.","No sustituyen a los agonistas GLP-1 cuando se busca pérdida de peso o beneficio cardiovascular."],"referencias":[{"cita":"AEMPS-CIMA. Ficha técnica de Sitagliptina Cinfamed 100 mg comprimidos recubiertos con película EFG.","url":"https://cima.aemps.es/cima/dochtml/ft/86323/FT_86323.html"},{"cita":"American Diabetes Association. Standards of Care in Diabetes—2026. Diabetes Care. 2026;49(Suppl 1).","url":"https://diabetesjournals.org/care/issue/49/Supplement_1"}],"imagenes":[{"ubicacion":"Sección de diferencias","descripcion":"Tabla comparativa de sitagliptina, linagliptina, saxagliptina y alogliptin con ajuste renal y seguridad cardíaca.","alt":"Diferencias entre los inhibidores de DPP-4"}],"keywords":["inhibidores dpp-4","sitagliptina dosis renal","linagliptina función renal","saxagliptina insuficiencia cardiaca","idpp-4 efectos adversos","diabetes adulto mayor","idpp-4 vs glp-1","curso farmacoterapia diabetes"],"mapa":{"centro":"iDPP-4","ramas":[{"titulo":"Mecanismo","icono":"Activity","nodos":["Inhiben DPP-4","Más GLP-1 y GIP","Insulina dependiente de glucosa"]},{"titulo":"Efecto","icono":"Target","nodos":["HbA1c modesta","Peso neutro","Bajo riesgo de hipoglucemia"]},{"titulo":"Riñón","icono":"Droplets","nodos":["Sitagliptina ajusta","Linagliptina no ajusta","Revisar TFG"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Pancreatitis","Artralgias","Penfigoide","Insuficiencia cardíaca"]}]},"proceso":{"titulo":"Cómo elegir un iDPP-4","intro":"","pasos":[{"titulo":"Definir el objetivo","detalle":"Control glucémico moderado, bajo riesgo de hipoglucemia y peso neutro.","icono":"Target","evidencia":"Meta clínica."},{"titulo":"Revisar TFG","detalle":"Elegir el fármaco y ajustar la dosis según la función renal.","icono":"Droplets","evidencia":"TFG registrada."},{"titulo":"Revisar corazón","detalle":"Evitar saxagliptina en insuficiencia cardíaca; preferir iSGLT2 si hay indicación.","icono":"Activity","evidencia":"Evaluación cardíaca."},{"titulo":"Educar","detalle":"Explicar el efecto modesto, la tolerancia y los signos de pancreatitis.","icono":"Users","evidencia":"Educación."},{"titulo":"Seguir","detalle":"HbA1c a los 3-6 meses y revisión de efectos adversos.","icono":"CalendarClock","evidencia":"Seguimiento."}]},"caso":{"titulo":"TFG 35 y alto riesgo de hipoglucemia","contexto":"Mujer de 80 años, diabetes tipo 2, TFG 35 ml/min, HbA1c 7,5 %, vive sola y ha tenido hipoglucemias con glibenclamida. No tiene insuficiencia cardíaca.","pregunta":"¿Qué opción oral es más razonable?","opciones":[{"texto":"Saxagliptina 5 mg al día sin ajuste.","correcta":false,"retro":"La saxagliptina requiere ajuste renal y se asocia con insuficiencia cardíaca; no es la mejor opción."},{"texto":"Linagliptina 5 mg al día, con revisión de la meta y seguimiento.","correcta":true,"retro":"La linagliptina no requiere ajuste renal y tiene bajo riesgo de hipoglucemia, lo que encaja en esta paciente."},{"texto":"Glibenclamida a dosis más alta.","correcta":false,"retro":"La paciente ya tuvo hipoglucemias; aumentar la sulfonilurea es peligroso."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Inhibidores de la DPP-4: mecanismo, perfil de seguridad y uso en poblaciones especiales$t$ AND deleted_at IS NULL
   ORDER BY id LIMIT 1;
  IF v_clase IS NULL THEN
    RAISE NOTICE 'Experiencias: no está la clase %. Se salta.', $t$Inhibidores de la DPP-4: mecanismo, perfil de seguridad y uso en poblaciones especiales$t$;
  ELSIF EXISTS (SELECT 1 FROM aula_lesson_blocks WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL) THEN
    UPDATE aula_lesson_blocks SET data = v_data, updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'experiencia' AND deleted_at IS NULL;
    v_n := v_n + 1;
  ELSE
    UPDATE aula_lesson_blocks SET deleted_at = NOW(), updated_at = NOW()
     WHERE lesson_id = v_clase AND type = 'texto' AND deleted_at IS NULL;
    INSERT INTO aula_lesson_blocks (lesson_id, type, sort_order, data)
    VALUES (v_clase, 'experiencia', 0, v_data);
    v_n := v_n + 1;
  END IF;
  IF v_clase IS NOT NULL THEN
    -- Videos arriba, la experiencia debajo y luego el resto (ver 123).
    UPDATE aula_lesson_blocks b SET sort_order = o.pos, updated_at = NOW()
      FROM (SELECT id, (row_number() OVER (ORDER BY CASE type WHEN 'video' THEN 0 WHEN 'experiencia' THEN 1 ELSE 2 END, sort_order, id) - 1)::int AS pos
              FROM aula_lesson_blocks WHERE lesson_id = v_clase AND deleted_at IS NULL) o
     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  IF v_n > 0 THEN
    INSERT INTO aula_republicaciones_aprobadas (course_id, aprobado_por, nota)
    SELECT v_curso, 'Dirección académica de Edvanta', 'Clases ampliadas con experiencia interactiva (124_experiencias_farmacoterapia_diabetes.sql).'
     WHERE EXISTS (SELECT 1 FROM aula_courses WHERE id = v_curso AND current_version_id IS NOT NULL);
  END IF;

  RAISE NOTICE 'Experiencias de %: % clases.', $t$Curso de Farmacoterapia de la Diabetes$t$, v_n;
END $exp$;
